#![forbid(unsafe_code)]
use sv_claude_kaggle::{need,parse,sha,R,LICENCIA};use std::{fs,path::Path,io::Write};use serde_json::json;
fn run()->R<()>{let a:Vec<_>=std::env::args().collect();need(a.len()==5,"MANIFIESTO ARCHIVO EXTRAIDOS INFORME")?;let mb=fs::read(&a[1]).map_err(|e|e.to_string())?;let m=parse(&mb)?;let b=fs::read(&a[2]).map_err(|e|e.to_string())?;need(m["archivo_sha256"]==sha(&b)&&m["archivo_bytes"]==b.len(),"Archivo no coincide")?;let root=Path::new(&a[3]).canonicalize().map_err(|e|e.to_string())?;let rows=m["archivos"].as_array().ok_or("Archivos ausentes")?;need(rows.len()==334&&m["generaciones_nuevas"]==23&&m["entregas_total"]==27,"Cobertura del archivo distinta")?;let mut n=0usize;let mut total=0usize;let mut seen=std::collections::BTreeSet::new();for r in rows{let s=r["ruta"].as_str().ok_or("Ruta")?;need(seen.insert(s)&&!s.contains('\\')&&!s.contains(':')&&!s.starts_with('/')&&s.split('/').all(|x|!x.is_empty()&&x!=".."&&x!="."),"Ruta insegura o duplicada")?;let p=root.join(s);need(!fs::symlink_metadata(&p).map_err(|e|e.to_string())?.file_type().is_symlink()&&p.canonicalize().map_err(|e|e.to_string())?.starts_with(&root),"Enlace o salida del perímetro")?;let f=fs::read(p).map_err(|e|e.to_string())?;need(r["sha256"]==sha(&f)&&r["bytes"]==f.len(),"Contenido o longitud distintos")?;n+=1;total+=f.len();}let report=json!({"conforme":true,"archivos":n,"bytes_logicos":total,"archivo_sha256":sha(&b),"archivo_bytes":b.len(),"manifiesto_sha256":sha(&mb),"inferencias":0,"licencia":LICENCIA});let mut o=fs::OpenOptions::new().create_new(true).write(true).open(&a[4]).map_err(|e|e.to_string())?;o.write_all(&serde_json::to_vec_pretty(&report).unwrap()).map_err(|e|e.to_string())?;println!("Descarga y extracción cotejadas en Rust: {n} archivos, {total} bytes");Ok(())}fn main(){if let Err(e)=run(){eprintln!("NO CONFORME: {e}");std::process::exit(1)}}
